def main():
    here = os.path.dirname(os.path.abspath(__file__))
    out = os.path.join(here, "a_core")
    os.makedirs(out, exist_ok=True)

    keys = [k for k, _ in ROWS]
    assert len(keys) == len(set(keys)), "rowKey 重複"
    for k, vals in ROWS:
        assert len(vals) == len(COLUMNS), f"{k} 欄數不符：{len(vals)}"
        for v in vals:
            assert "\x1f" not in v, f"{k} 含 U+001F（§6.3 應由管線硬失敗，不放進正常 fixture）"

    # input.csv：UTF-8 with BOM、CRLF，比照來源 205_2.csv
    buf = io.StringIO(newline="")
    w = csv.writer(buf, lineterminator="\r\n", quoting=csv.QUOTE_MINIMAL)
    w.writerow(COLUMNS)
    for _, vals in ROWS:
        w.writerow(vals)
    with open(os.path.join(out, "input.csv"), "wb") as f:
        f.write(b"\xef\xbb\xbf" + buf.getvalue().encode("utf-8"))

    # rows.json：rowKey → 16 欄字面值。oracle 用 rowKey 指涉列，與 CSV 列序無關。
    with open(os.path.join(out, "rows.json"), "w", encoding="utf-8", newline="\n") as f:
        json.dump(
            {"columns": COLUMNS, "rows": {k: dict(zip(COLUMNS, v)) for k, v in ROWS}},
            f,
            ensure_ascii=False,
            indent=1,
        )

    print(f"input.csv: {len(ROWS)} 列")
    print(f"rows.json: {len(ROWS)} 個 rowKey")


if __name__ == "__main__":
    main()
